{
  "criteria": [
    {
      "criterion": "claridad",
      "score": 3,
      "finding": "El requisito mezcla dos condiciones contradictorias o superpuestas: 'generarse automáticamente cada día' y 'solo cuando el gerente los solicite manualmente'. Queda sin qué grado de automatización se aplica si hay solicitud manual, generando ambigüedad sobre el gatillo real.",
      "recommendation": "Definir claramente si el gatillo es exclusivo la solicitud manual, o si la generación diaria es automática y el gerente la consulta/descarga manualmente."
    },
    {
      "criterion": "especificidad",
      "score": 4,
      "finding": "Se menciona 'datos necesarios' sin precisar qué datos ni formato. No se especifica el alcance de los datos (qué campos, rangos, filtros) ni la estructura del reporte.",
      "recommendation": "Definir los datos concretos a incluir (p. ej., ventas totales, unidades por producto, región) y el formato de salida."
    },
    {
      "criterion": "atomicidad",
      "score": 2,
      "finding": "El requisito es compuesto: combina la frecuencia (diaria), el gatillo (solicitud manual) y el contenido (datos necesarios). Mezcla tres comportamientos independientes en una sola oración.",
      "recommendation": "Dividir en requisitos atómicos separados: uno para la frecuencia, otro para el gatillo, y otro para el contenido mínimo."
    },
    {
      "criterion": "completitud",
      "score": 2,
      "finding": "Falta información esencial para desarrollar y probar: qué datos conforman 'los datos necesarios', con qué frecuencia exacta se ejecuta 'cada día' (hora exacta), y si la solicitud manual invalida la generación automática o es el único gatillo.",
      "recommendation": "Especificar los campos de datos, la hora exacta de generación diaria y la lógica del gatillo manual vs automático."
    },
    {
      "criterion": "consistencia",
      "score": 3,
      "finding": "Contradicción interna: 'generarse automáticamente cada día' implica un gatilo temporal recurrente, mientras que 'solo cuando el gerente los solicite manualmente' implica un gatilo humano. Los dos no pueden ser la única fuente de generación sin una lógica de combinación que no se especifica. Además, el contexto indica que los gerentes consultan reportes desde la web, lo cual sugiere una consulta bajo su criterio, no necesariamente una generación sobrerreglada.",
      "recommendation": "Aclarar la lógica de gatillo: si la generación es automática diaria y el gerente la consulta, o si la generación ocurre exclusivamente bajo solicitud manual. Eliminar la contradicción entre 'automático cada día' y 'solo manual'."
    },
    {
      "criterion": "factibilidad",
      "score": 5,
      "finding": "Desde el punto de vista técnico, generar reportes diarios y bajo solicitud es factible con los sistemas actuales. No hay restricciones técnicas declaradas que lo hagan imposible.",
      "recommendation": ""
    },
    {
      "criterion": "verificabilidad",
      "score": 2,
      "finding": "No hay forma objetiva de verificar si el reporte se generó 'cada día' bajo las condiciones mezcladas, ni qué datos se consideran 'necesarios'. Faltan umbrales de tiempo, condiciones lógicas y lista de campos para poder comprobar el cumplimiento.",
      "recommendation": "Definir horarios exactos, condiciones de gatillo y la lista completa de campos/datos obligatorios en el reporte."
    },
    {
      "criterion": "trazabilidad",
      "score": 4,
      "finding": "No se asigna un identificador único ni se declara el actor/necesidad de origen explícita. El contexto menciona que los gerentes consultan reportes desde la web, lo que permite relacionarlo con roles de usuario, pero el requisio en sí no tiene etiqueta ni origen claro.",
      "recommendation": "Añadir un identificador (p. ej., REQ-XX) y enunciar el actor origen (p. ej., 'Solicitud del gerente de tienda')."
    },
    {
      "criterion": "ausencia_ambiguedad",
      "score": 2,
      "finding": "Términos ambiguos detectados: 'cada día' (no especifica hora ni zona horaria), 'datos necesarios' (vago y sujeto a interpretación), 'generarse automáticamente' (no define si es bajo gatilo, schedule o evento), 'solicite manualmente' (no define canal o frecuencia máxima de solicitud).",
      "recommendation": "Sustituir los términos vagos por valores o condiciones medibles (p. ej., 'a las 06:00 UTC', 'ventas del día anterior', 'formato PDF/CSV con X campos')."
    },
    {
      "criterion": "criterios_aceptacion",
      "score": 1,
      "finding": "No hay criterios de aceptación explícitos ni condiciones medibles de las que derivarlos. No se especifica cuándo el requisito está satisfecho (¿qué reportes se generaron?, ¿qué datos incluyen?, ¿bajo qué condiciones exactas?).",
      "recommendation": "Definir criterios de aceptación con estructura Dado/Cuando/Entonces y condiciones medibles (p. ej., 'El sistema genera un reporte CSV con 15 campos a las 06:00 UTC cada día; el gerente puede descargar el reporte desde la web bajo solicitud')."
    }
  ],
  "ambiguous_terms": [
    {
      "term": "cada día",
      "reason": "no especifica hora, zona horaria ni frecuencia exacta dentro del día"
    },
    {
      "term": "datos necesarios",
      "reason": "concepto vago sin lista de campos ni criterios de inclusión"
    },
    {
      "term": "generarse automáticamente",
      "reason": "no define gatilo (schedule, evento, manual) ni comportamiento al interactuar con solicitud humana"
    },
    {
      "term": "solicite manualmente",
      "reason": "no especifica canal, mecanismo ni si invalida la generación automática previa"
    }
  ],
  "is_compound": true,
  "missing_information": [
    "hora exacta y zona horaria para la generación diaria",
    "lista completa de campos/datos que conforman 'los datos necesarios'",
    "lógica clara entre gatillo automático diario y solicitud manual (si son exclusivos o combinados)",
    "formato de salida del reporte y canal de solicitud manual"
  ],
  "clarification_questions": [
    "¿La generación diaria es automática con horario fijo, o solo se genera bajo solicitud manual del gerente?",
    "¿Cuáles son exactamente los datos/campos que deben incluirse en el reporte de ventas?",
    "¿El gerente solicita el reporte a través de la interfaz web, un correo electrónico o otro canal?",
    "¿Se debe respetar una hora específica del día para la generación automática, o es bajo demanda continua?"
  ],
  "summary": "El requisito es compuesto y contradictorio al mezclar generación automática diaria con solicitud manual exclusiva. Faltan definiciones de datos, horarios y lógica de gatillo. No hay criterios de aceptación medibles. Es necesario dividir el requisito en partes atómicas y especificar condiciones concretas."
}

{
